    (1, 23, "ወስዙሉ አራዊተ ምድር፡ ወለዙሉ ክዕዋፈ ሰማይ ወ, ዙሉ ዘይትሐወስ ዲበ ምድር ዛክ መንፈሰ ሕይወት ፡ ወዙ ሉ ሐመልማለ ሣዕር ይኩንክሙ መብልፀ፡ ወክ? ክሣሁ።"),
