    (1, 25, "መወክነ ሌሊተ ወጾኽቁ ፡ ወክ፣ ስድስተ ዕፅተ » af ዋትዮጵያ ኦርቶዶስ ተጥጨዶሯ ቤተ € ይፆሪት ዘልደት ፣ ምፅው | [i ምድረ ኢትዮጵያ።"),
