    (3, 15, "፥ ወጸግዘናኛ ስቃ ወኮቤሎ ቃየል ለአቤል እኀ.ሆሁ ነዓ ንሑር ሐቅለ ፣ ወከነ አንዘ ሀለ. ገዳመ ተንሥኣ ቃየል ላዕለ አቤል አትሆሁ ወቁ።"),
