    (6, 22, "ወክም ድግረ አይሣ እአሣዘ ፃሣ ይትገበራ ለምድር ' ወተ ከለ ዐፀደ ወይን = ወስሰትየ አምኔሁ ወሰክረ ወተፀርቀ በውስተ ቤቱ።"),
