    (7, 3, "መስበ ጽሕወ ኖሣ ኣምስከረ ወይኑ ኣአመረ ዙሎ ዘገብረ ሎቱ ወልዱ ዘይንኣስ ) ወይቤ ኖሣግ ርጉመ ለይኩን ክነአን ወገብረ ወነበፊ ይኩን ለአጎኀዊሁ።"),
