    (
        9,
        20,
        "WR oN Ly) bro oT [yy a ዙሉ አፍራስ ዶም =ንሞራ = h3 ወፊ መነሥእም ለሎጥ ወልደ እሁ ለሕብራም ei IN ' ‘| | ye የ - | B ቶ | | ወበጽሑ አለ አምሠጡ ወዚንውዎ ለራ እንዘ UA ጢ ግቡረ-ኃበ ዕ8 ምስለ አምሮስ እራ ለኤስክል ' መለክ ክ) ውናን ኣለ t ሩበን እሙንቱ iy Hi ወስበ ሰምዐ አብራም ከመ tie ሎጥ ak. እትሁ . 18 ጐለቆሙ ለአሊክሁ ወለዙሎሙ በብጸ ቤቱ ወኮኑ Ffiወg ወዪገኛሙ ወተለዎሙ እስክ ዳን = ወበጽሖሙ ሴኬሊተ ምስለ ደቂቁ ወቀተሎሙ ወጽገ TE ኖሙ እስከ ኮቤር እንተ ፀጋማ ለደማስቁ = = | I ' | ea ወነሥኦሙ አብቅሊሆሙ ወነሥጾ ስሎጥሂ ወልይ አጭ ሁ ወንዋዮሙኒ ወአንስተኒ ወሕዝበኒ አእተወ።",
    ),
    (
        9,
        21,
        "ወወጽአ ንጉሠ ስድም ወተቀቃበሎ አም ድግሪ ንብእ አም ዳ፱ ቋቱ ለቱሎድቅምር መዳሃጋሥት እል ምክሔኩሁ [yy ላተ ሴዎ ወውአቱ ገዳም ዘመንግሥቱ ውእቱ ፥ ወመልክከ ጴዬዴቅ አምጽአ ግኸስተ ወወይነ ፡ ወክህኑ ለኣ ግዚአብሔር ልዑል ውአቱ፡ ወንግመ ሰሌም ውእቱ።",
    ),
    (9, 22, "ወበረክ ለአብራም ወይቤሎ ቡሩኩ አብራም ለአግዚክ ብሔር ልፁል ዘፈጠረ ሰማየ ወምድረ።"),
    (9, 23, 'ወቡሩክ እግዚአብሔር ልፁል ዘሾግብኦሙ ለጸላአትክ ውስተ አዬዴክ "ወወሀበ አብራም ፀሥራተ አድ አምሆሉ።'),
    (9, 24, "ወይቤሎ ንጉሠ ሰዶም ለአብራም ህበ ሰብጸ፡ ወጥሪ ተሰ ግደጉ ለክ።"),
    (
        9,
        25,
        "| ወይቤሎ ክብራም ለንጉሠ ስዶም ክሌዕል አዴየ ገበ አግዚአብሔር ልዑል ዘገብረ ሰማየ argc ከመ ኢይነሥክአ ኢ ፈትለ ወኢ ቶታነ ጸሣክን አምንዋ ይክ ከመ ኢት በል አነ አብዐፀይክዎ ሶአብራም ኮንበለ ዛበ ልዑ ሰብሕየ እክል።",
    ),
    (9, 26, "ዳእሙ አዴው ክለ ቃሩ ምስሔየ ኤስክከል ወመምሬ አሙ ንቱ ይንሥኡ ክፍሎሙ።"),
    (
        9,
        27,
        '" ወእምድግረ ዝንቱ ነገር ዢነ ቃለ አግዚአብሔር ኀበ . አብራም በራአይ ወድ ቤሎ ኢትፍራህ አብራም .አነ ፀን Dh መአፀብየክ ወፀስብከሂ ብዙና ውአቱ ጥቀ በግቤየ = ወይኬሎ ኣብራም ምንት ውእቱ አግዚ።',
    ),
    (
        9,
        28,
        'ዛት ሁበኒ ወና የትዮጵያ ኦርቶዶክስ ተጥሕዶ ቤተ he eal ሁ አመውት እንዘ አልብየ ውሉድ ፡ ወናሁ ወልደ ማሴቅ .ዘይደማስቋ ዘይብልቓ ኢያውብር ዘእምነ ወልደ ዘመድየ ውእቱ ይወርፅስኒ = ) ይቤ ኣብራም እስመ ሊተ aban: HCA ወልደ " ዘመድየ ውእቱ ይወርስሰኒ።',
    ),
    (
        9,
        29,
        "ወበጊዚሃ. ከነ ቃለ አግዚአብሔር ሓበ አብራም ወይ ቤው ውአቱስ ኢይወርስሰክ አላ ክልእ ዘይወጽእ አምሐ | ቋክ ውአቱ Pneih x ወኣውጽኦ አፍኣ ወይቤሎ ነጽር ' ውስተ ሰማይ ላዕለ ወኀ’ልቋቆሙ ለከዋክብት ለአመ ትክል PR ወይ ቤስ ከማሁ ውእቱ ዘርእከ።",
    ),
    (
        10,
        1,
        "PN የኢትዮጵያ ኦርዶክስ ተጥሕዶ ቤተ አሪት ዘልደት ፡ ምዕራፍ Pe ወጸምኖ አብራም ለእግዚክብሔር ወተሣለቆ ሎቱ ጽድቁ | ወይቤሎ አነተ ሇጸቱ አግዚአብሔር አምላክከ ዘኣውጻ አኩክ አምድረ ከላውዴዎን ከመ አህ ብከሃ ለዛቲ ምድር ትትዋረሳ።",
    ),
    (10, 2, "ወደ ቤሎ እግዚዖ» በምንት ጸክአምር ከመ አወር።"),
    (
        10,
        3,
        "ወይቤሎ ንሣእ ለከ ላሕመ ዘር ዓመቱ ፣ ወጠሊ ዘር. ዓመቁ ፡ ወስግዐ ዘ፫ ዓመቱ ! ወማዕነቀ ወርግበ , ወንሣአ ከማሁ ዘንተ ዙኵሎ ወምትሮሙ. አማአከሎሙ ፡ ወለአዕዋ '\"ቋ፳ሰ ኢቸምትሮን።",
    ),
    (
        10,
        4,
        ".. -. ወነሥአ ሎቱ ከማሁ ዘንተ ዙሉ ወመተሮሙ አማኣክ ሎሙ ወአንበረ ዘተመዥረ ጾንፃረ ቢጹ ወለአዕዋፍስ ኢመ ተርፎን = SS EIS ts £ HN is a, ] ) Ri aaé አልክቱ እፅዋፍ, ABA አብድንት ወነበረ ክብራ ጓቤሆሙ ወጦ ወቦበ; የክርኻ ሐድ ድንጋፄ መጽ ለ ' ሣሩም ጽልመት ወፀlድ መ RY Pn አግዚአብሔር ስብራ ከመ. 0h RncNY ይከተ #ላ Oንተስ ተሐውር ወትን w5ፍይ.. a; T | ወnራብዕ xe: ም ይገ | os pi ; aan hs ጊዜ eaር4. Dy መጽ iF ወመጽ እላ እቱ: ዘተመትረ ወበይእቲ ዕለት አቀመ አግዚአብሔር ለጸብራም ኪዳነ L es) Ly YR) 1) ተ ድ ) ፲ ፳ ዓ ች ' ወ ) a ; ጋ ; ጊ | ኢ እ 0, ; ዓ Ry | ቸ | ' | | ት“ወመጽጸ አቶን RRnEh ወግለፈ ኣንቱ ማእከሉ ለው | | 1 ዘጸሰፈዎ ወይቤሎ ለዛርእክ ኣሁበ ለዛቲ ምድር አም፣ ፈልገ ግብጽ አስክ ፈለግ ዐቢይ ፈለገ ጴሌፍራጥስ።",
    ),
    (10, 5, "| . ዘቄኔዎስ ወዛቁኔሣዮስ ወዛቁሄሜሎስክ።"),
    (10, 6, ". ; ወዘቤጢጤዎን ወዘፌርቬዙዎን ወዘፈራዮን።"),
    (10, 7, "| '\" ወዘአሞሬዎን ወዘከናኔዎን ወዘጌርጌሴዎን ወዘኢያቡሌሴ | | Pን።"),
    (10, 8, "ማስራብ ብሕበቢ.ቱ ለአብሩም ኢወለደዥ ሎቱ pas አመ ት ግብፃዊት ኣንተ ስማ. አጋር።"),
    (
        10,
        9,
        "ወትቤሎ ስድ ለኣብራም ናሁ ፀፀወኔ ‘ኣግዚአብሔር ን - ey ብ የኢትዮጵያ አርቶዶክስ ተጥሕዶ ቤታ ዩሯ ኦሪት ዘልደት ፣ ምፅራ Eo ከመ ኢይወልድፎ ሑር ጎበ አመትየ ከመ ትጸድ ኣም ኒሃ፡ ወሰምክ አብራም ቃላ ስስራ ብእክሲቱ።",
    ),
    (10, 10, "መወኝሥአታ ስራ ለአጋር አመታ ግብፃዊት ኣምድግረ ፲ ዓመት ዘኀደረ አብራም ውስተ ምድረ ከነአን ወወ ሀበቶ ለአብራም ትኩኖ ብኣዪተ።"),
    (
        10,
        11,
        "ወበ አብራም ኀበ አጋር ወፀንፅት ወስበ ርአየት ከመ ፀንሰት ጓደንት አክብሮታ ለአግዝአታ = | ወትቤሎ በራ ለአብራም አትገፉዕ አንሰ አምኔክከ ዞነ ወሀብኹክ ጸመትየ ውስተ ሣፅንከ ወሶበ ርአየት ከመ ፀንሰት ጓደንት አክብሮትየ፡ ለይፍቻታሕ እግዚአብሔር ማአክሴየ ወማአከሴሔክ።",
    ),
    (10, 12, "ወይቤላ አብራም ለስራ ብክሲቱ ነያ አመትኪ ውስተ ኣዴኪ.ግበርያ ዘከመ ይኤድመኪ ! ወሣቀየቻታ ለራ ሓይጋር ወተሣጥአት እምኔሃ።"),
    (
        10,
        13,
        "ወረከበ መልአከ እግዚዞጾብሔር በጎበ ፀዘቅተ ማይ በገ ዳመ ቡር በፍኛናት = ወይቤላ መልአክ አግዚአብሔር አጋር አመተ ስራ እም አይቴ መጻአኪ ወአይቴ ተሐውሪ! ወትቤሎ እምነ ገጸ ሶራ እግዝእትየ ኮትኻሣጣክ አንስ።",
    ),
    (
        10,
        14,
        'ወይቤላ መልአክ አግዚአብሔር ግብኢ ግበ አግዝአትኪ - ወክትሕቲ ርአስኪ ታሕቱ ክአይዴሃ = ወይቤላ እግዚአብሔር አብኻኘ አበዝኖ ለዘርእኪ እስክ ኢይትኋለቀ" እምነ ብዝጭ።',
    ),
    (10, 15, "ወይቤላ መልአክ አግዚአብሔር ናሆ ፅንስት ጸንቲ ወት ወልዲ ወልደ ወትሰምዬፉዮ ስሞ ይከቦማኤል አስመ ሰምፀ አግዚአብሔር ሥቃየኪ።"),
    (10, 16, ") ወይከውን ብአሴ ሐቅል እደዊሁ ሓኣዕለ ዙሉ ወአድወ ዙሉ Abb ወየጎድር ቅድመ አጎዊሁ።"),
    (10, 17, ".ወጸው0ት አጋር ስመ አግዚአብሔር ዘተናገራ ወትቤ አንተ አግዚኦ ዘመሀከኒ፡ አስመ ቅድሜየ ርኢክዎ ለሄአስ ተርአዩኒ።"),
    (10, 18, "| iH Ly) ወበእንተ ዝንቱ ሰመየቶ ከሞ. ለውእቱ ወካቕች ክቅድ | ሜየ አስተርአየኒ ማሕከለ ቃዴስ ወማእከለ ጋሬድ ወገብ አች አጋር።"),
    (10, 19, "ወአም ድግሪ ዝንቱ ወፅዪት ሎቱ አጋር ለአብራም ወሰመዮ ስሞ አብራም ለውእቱ ሕፃን ዘወለድደት ሎቱ አጋር ይስማኤል።"),
    (10, 20, "ወወ ዓመቱ ለአብራም ሕመ ወለደት ሎቱ አጋር ይስማኤልሃ።"),
    (
        10,
        21,
        'ወክምዝ አመ ኮኖ ለዞብራም ጓወ ዓመተ አስተርአዮ አግዚጾብሔር ለአብራም ወይቤሎ አሃ ውአቱ አግዚጸብ Bh ሔር ፈጣሪክ ዘቃርኩ ቅድሜካ አሥምር ቅድሜየ ወኩን ንጽሐ " ወእሠይም ኪዳነ ማእከሌየ ወማእክሌክ ወአበዝግክ ዋቀ።',
    ),
    (
        10,
        22,
        "ወወድቀ ኣብራም በገጹ ወይቤሉ አግዚክ ብሔር ለኦ ብራም = ‘ናሁ ክአሠይም ኪዳንየ ማሕክሌዩ ወማእhkh ወትክ ) ውን አስ ሰብዙኃን ኣሕዛብ = 'ወኢይሰመይ አንክ ከምዘ አብራም ክላ አብርሃም ይሰ መይ ፡ አስመ አበ ብዙኃን አሕዛብ ረሰይኩክ።",
    ),
    (10, 23, "br ወአስተበዝሣክ ጥቀ. ፈድፋደ ወክሬስዩክ ከመ ይ እአምኔክ አሕዛብ ወነገሥት።"),
    (
        10,
        24,
        'ወእሠይም ኪዳንየ ማሄከሌያ ወማአክሌክ ማእከለ ዘሮ | እዘ ኣምድሣዳሬክ በትውልዶሙ ከመ ይኩንከ" 7 ዘለ ; ለም ከመ አ፣ ውአቱ አግዚአብሔር አምላክከ. መለAyርRh እምድሣሬክ።',
    ),
    (
        10,
        25,
        "- ወክሠቭበ ለዛቲ ምድር ኣንተ ውስቴታ ቶችኝድር ለዘርእክ ወዙሰሎ ምድረ ከነዶን ከመ ይኰንንዋ ለም ፡ ወአክው ኖሙ አምላክከሙ = ወይ እማዚአብሔር ለአብርሃም አንተ ዕቀብ RS 'ወዘርክክ ክአምድዓሬከ በት ውልድሙ።",
    ),
    (
        10,
        26,
        "| ወዛቲ ይእቲ ሥርዓትየ እንቱ ትትፀቀብ ማሕክሕየ ወማ እክሌክ ወማይአከለ ዘርእከ ዙሎ ተክፅትክሙ ከተማ ነፍስትኸሙ = ወይኩንክሙ ትአምርተ 'ለኪዳንየ ማኣከሌየ ወማእክ | ቤኸሙ።",
    ),
    (
        10,
        27,
        "እም ጽዳሬክ ከመ ትትንዛሩ ' ወጻሕፃን ትኘዝርዎ በሳምንት ዕለት ወዙሎ ተበፅተክሙ በትውልድክሙ ወልደ ቤትክሙኒ ወዙሎ ዛተሣየጥ ክሙ በወርቅክሙ = ወትኩን ሥርኝትየ ውስተ ሥጋክሙ ለኪዳንየ ዘለዓለም።",
    ),
    (10, 28, "ወዘለ-ተገዝረ ክተማ ነፍስቱ በምንት ዕለት ለትደም ሰስ ይአቲ. ነፍስ ኢአምነ ዘመዳ፣ክስመ ሣንት ሥርዓትዩየ።"),
    (
        10,
        29,
        "የኢትዮጵያ ኦርቶዶክስ ተኖሕዶ ቤተ | ኦሪት ዘልደት ፡ ምፅራፍ ወይቤሎ አግዚአብሔር'ለአሓብርሃም ይራ ብኣሲትክ ኢች EY ስማ Aes | እስመ አርክ ወአሁባ ውሉደ -አምኔሽ ፥ አሕዛብ ወነን ሥተ አሕዛብ ይወፅኡ እምኔሃ = ) ወወድቀ አብርሃም በገጹ ወሰሐቀ ወሐለየ በልቡ እንሃ ይብል እንዘ ሄትኑ ዓመት ሊተ እወልድ ጸነ ወልደ ፡ ወሳ ራኒ እንተ ፮ ዓም ላቲ ትወልድ።",
    ),
    (10, 30, "ወይቤሎ አብርሃም ለእግዚአብሔር ዝንቱ ይስማኤል ውእቱ ዳክሙ ይሕየወኒ በቅድ ሚክ አስተበሞሥዓክ አግዚአ።"),
    (
        10,
        31,
        "ወይቤሎ እግዚአብሔር ለአብርሃም አሆ! ወናሁ ሳራኒ PN የትዮጵያ ኦርቶዶክስ ተዋሕዶ ቤተ ቛ አሪት ዝልደት , ምዕ ss ብአሲትክ ትወልድ ለክ ወልድ ወትስምድዮ ስሞ ይስቁቅ፡ ወአቀውም ሥርዓትየ ሣቤሆሁ ለኪዳጃን ዘለዓስም መለዘርኡ እም ድሣሬሁ።",
    ),
    (
        10,
        32,
        ". ወበእንተ ይስማኤል፤ኒ ናሁ ፀማዕኩከ አበርክ ወአበዝና ወጸስቦተሽዃዝያ ገብሮ ሕዝበ ዐቢየ = ወኪጃዳንየሰ ክቀውም ምስስ ይስሐፍ ከትወልድ ለክ ስራ ፡ በዝንቱ ጊዜ በክልአት ዓመት።",
    ),
    (
        11,
        1,
        "ወለበ ፈጸመ አግዚአብሔር ተናግማሮቶ ፀወርግ አምኀቤሁ ስጾብርሃም = ወነሥአ አብርሃም ለይስማኤል ወልዱ ወለኩሉ ልፎ ቤቱ ፡ ወለዙሉ ተበዕት ዘተሣየጠመ በወርቁ ወለዙሉ ሰብአ ቤቱ, ወገዘሮሙ ክተማ ነፍስቶሙ በከመ ይቤሎ አግዚ አብሔር = ) ወይእተ ዞሚረ ወዘ ዓመት ሎቱ ስጾብርሃም አመ ተገዝረ ከተማ ነፍስቱ።",
    ),
    (11, 2, "ወለይስማኤልይኒ ወልዱ ፲iወ፫ቱ ዓመቱ ክመ ተገዝረ።"),
    (11, 3, "ወበጊዜሃ በይእቲ ዕለት ተገዝረ አብርሃም = ወዙሉ ሰብክ ቤቱ ተገዝሩ።"),
    (11, 4, "Rs. Lc» ህዘብ እ ዘኔ መሩ ee Pn ቸጭ መኝ ሠጀቲ ስ አታ Sn።"),
    (11, 5, "ወአስተርአዮ አግዚአብሔር ለአብርሃም በቦግበ ዕፀ መም ፎሬ አንዘ ይነብር ግበ ኖሣተታ ሐይመት ቀትረ።"),
    (11, 6, "ወበበ አልፀለ አፀይንቲሁ ነረ ወናሁ ሠስከስቱ ክደው ይቃውሙ መልፅልቴሆሁ ፣ ወርእየ ወሮጸ ለተቁብሎቶሙ ኣምኖሣተ ሐይመት ወሰገደ ውስተ ምድር።"),
    (11, 7, "ወይቤሰ አማዚኦ እመ ረከብኩ ምገስ በቅድመ i ቴክ ኢትሣልፍ አምገብርክ።"),
    (
        11,
        8,
        "ናምጽእክ ለክሙ ማየ ወንሕጽብ አገሪክሙ ወታጽልሑ ታሕተ ዕፅ= ወናም ጽእ ኅብስተ ወትብልፁው ወእምዝ ተወው ግበ ሐላይክሙ አምከመ ግዳሥክሙ. ጎበ ንብርክሙ ወይቤ ልዎ ግበር ከማሁ በከመ ትቤ።",
    ),
    (
        11,
        9,
        "ወርሮጳ አብርሃም ግበ ሳራ ብኣአሲቱ ውስተ ወድመታ ወይቤላ አፍጥኒ ወአብሣር ሠለስተ መስፈርተ ሥግዳሌ Rይ RE 73 li ወግበሪ ዳፍንተ = ወሮጳ አብርሃም ጎበ አልሕምት ወነሥአ ጸሐድዴ ላሕመ ንኡሰ ወሠናየ ወወሀበ ለቍልዱሁ ወአፍጦነ ገቢሮቶ = ወክምጽአ ዕቋነ ወመዓረ ወውእተ ላሕመ ዘገብረ ወአቅ ረበ ሎሙ ወበልፁ ፡ ወውእቱሰ ይቀውም ግበ ዕፅ ወይ ሜጥዎሙ።",
    ),
    (
        11,
        10,
        "t ወይቤሎ አይቴ ሳራ ብኣሏትክ፡ ወይቤሎ ነያ ውስተ ሐይመት = ወይቤሎ ዕበ ገበከዅ ክመጽእ ጎቤክ ዓመ ከመ ዮም ወትረክከብ ዳራ ወልይ ወሰምበፀት ሳራ አንዘ HE ሣበ ኝግት አንዘ ሀለወት ድግሬሁ።",
    ),
    (
        11,
        11,
        "ኦሪት ዘልደት ፡ ምዕራ የኢትዮያ አርቶዶክስ ተጥሕዶ ቤተ . ወአብርሃምስሰ ወሳራ ልህቐ ጥቀ ወሣለፌ መዋዕሊሆሙ፣ ወሣደጋ ለሳራ ትክቶ አንስት = ፡ መሰሐቀት ሳራ በበሕቲታ እስመ ትቤ በልበ. ዓዲየኑ nt» ይእዚ፡ ወእግዚ. ኣየሃ ልህቀ።",
    ),
    (
        11,
        12,
        "(yah v ወይቤሎ እግዚአብሔር ለኣብርፇም ምንት አስሐሓቃ ለሳ ደ በባሕቲቻታ አንዛ ትብል ዓዲየኑ አስከ ይአዜ፣ ወአማ ንኑ እአወልድ AES ልህቀ ወናሁ ረስእኩ s ቦኑ ሃገር ዘይበአና ለአግዚጸብሔር . በዝንቱ ጊዚ. ሶበ ገበአ ኀቤከ በላብፅፀታ ተረክብ ጓራ ወልድ።",
    ),
    (11, 13, "'መክሕይት ብራ አንሣ ትብል ኢሳሐቁ አስመ Ps BEN ጾላ ሰሐቁ።"),
    (11, 14, "ወተንሥክአ' ክልኤቱ አዶው አምህየ ወአንጸሩ ወይፋ መንገለ ሰዶም ወገሞራ ወሖረ እብርሃም ም ክስሴሆሙ ያስ ተፋንዎሙ፡ ወተመይጠ አብርሃም ወቆመ ቅድመ አግዚ ጸብሔር።"),
    (11, 15, "ወይቤሎ ኣግዚአብሔር .ጺየ የሣብኳ አም ቀቍ-ልፍየ ኣዳር ሃም ዝዘእገብር ኳነ።"),
    (11, 16, "አስመ ሕዝበ ኃቢየ ወብዙንኝ FMR ወይት ረኩ በቱ ሹኵሎሙ አሕዛበ ምድር።"),
    (
        11,
        17,
        "እስመ አአምር ከመ ሀለዎ ለአብርሃም የአዝዘሙ ለደ ቁቁ ወለቤቱ ወያፅቅበሙ ፍናዊሁ ለአግዚጸብሔር ከመ ይግበሩ ምጽዋት ወፍትሐ ፡ ክመ ይግበር ሎሙ እግዚ ' ኣብሔር ኵሎ ዘይቤሎ ለአብርሃም = ወይቤሎ እግዚአብሔር ለጻብርሃም ጽራሐሙ ለፀዶም ie NE በጽሐ ኀቤየ ወጓጢዉእአቶሙኒ በዝጋት ጥቀ።",
    ),
    (
        11,
        18,
        "አወርድ አንክፅ ወእርኣይ ለአመ በከመ ጽራሐሙ አን + ትመጽእ ቤያ ይፈፌጽምዋ ወእመ አክሰ አአምር = LF Ly ' 1 ሠወስበ ተመይጡ እምህየ አልክቱ እደው መጽኡ ውስተ. : በዶም ፡ ወአብርሃም ስ ሀሎ ማዲ iy ቅድመ አሣ ' ዘብሔር።",
    ),
    (
        11,
        19,
        "ጦመቀርበ አብርሃም ወይቤ ጸ.ታማስን እግዚጾ ጻድቃነ ምስለ ኃጥአኝ '፡ ወኢ.ዴኹቡን ጻድቅ ከመ ኃጥእ = ለአመ ሀለዉ ሣምሰ ጻድቃኝ በውስተ ሀገር ታማስ ናሙኑ ወኢታሐዩኑ በእንተ 1 ጻድቃን ኵሎ ብሔረ።",
    ),
    (11, 20, "ሐሰ ለክ አማኦ ኢትግበር ዘንቱ ነገረ ወኢትቅትል ጻድቃነ ምስለ ኃጥአን ፡ ሐሳ i ለዙላ ምድር iE ግበር ዘንተ ደይነ።"),
    (
        11,
        21,
        "2 i የኢትዮጵያ አርቶዶክስ ተወሕዶ ቤተ aig . አሪት ዘልደት ፡ ምፅ ወይቤሎ እግዚአብሔር ለአብርሃም ለአመ ረከብኩ ውክት ህገረ ሰዶም 3 ጻድቃነ አድኝን ዙሎ ሀገረ በአን ቲአሆሙ።",
    ),
    (11, 22, "ወአውሥአ አብርሃም ወይቤ ይእዜ አሓዝኩ አትናገር ምስለ እግዚአየ እግዚአብሔር ፣ ወኣንስ መሬት ወሐመድ ኣነ።"),
    (11, 23, 'ወአመስኬ ውኅዱ እም አልክቱ ጻድቃን ጀቱ ታማስንኑ ዙስ" ሀገረ በአንተ አለ ውጎኀዱ ፣ ወይቤሎ እግዚጸብጣdር ለእመ ረከኽኩ በህየ ጓወጀተ ኢያማስን በአንቲአሆሙ።'),
    (11, 24, "ወይቤሉ” አብርሃም ለአመጨ ተረክቡ በሀየ 3! ወይ ቤሎ አግዚአብሔር ፡ ኢያማስን በአንተ ፳።"),
    (11, 25, "ወደገመ ዓዲ ብሂሎቶ አብርፃነም ወይቤሎ አመሰዜ ተረ ክቡ በሀየ 8፳፡ ወይቤሎ ጺያማስን በአንተ 8።"),
    (11, 26, 'ወይቤሎ አብርሃም ክስመ ተበዋቋኩ አትናገር "ምስለ አግዚክየ እግዛ, አብሔር፡ ለአመጨ ተረክቡ በህየ’ ፳፡ ወይቤሎ ኣ.ያማስን በአን ፳።'),
    (11, 27, "ወይቤሎ አብርሃም አብሐሂ እግዚአ እንብብ ዓዲ ለእ መኬ ተረክቡ በየ ፲ቱ ፡ ወይቤሎ ኢያማስን በአንተ ፲ቱ።"),
    (11, 28, "ወለበ አዳለቀ ተናግሮቶ’ ለአብርሃም - ዳስፈ እግዚአብ ሔር፡ ወክብርሃምኒ ገብክ ጎበ ምንበሪሁ።"),
    (11, 29, "ወበጽሑ አልክቱ ፪ቱ መላክክት ውስተ ሰፉም ፍና ሰርክ፡ ወሎጥ፤ኒ ሀሎ ይነብር ውስተ አንቀጸ ሀገረ ሰዶም ወበ ርአዮሙ ተንሥአ ወተቆበሎሙ ወሰገዴ ሎሙ።"),
    (11, 30, "ወይቤሎሙ ጸጋ አዝትያየ ገግ ግበ ቤተ ገብርክሙ ወሣኝ ድሩ ወተሐፀቡ አገሪክሙ ወትጊጌው ወትሑሩ ፍኖተክሙ፡ ወይቤልዎ አልቦ፣ አላ ነጓድር ውክከተ መርግብ።"),
    (11, 31, "ወአገበሮሙ ወግጎው ሣቤሁ ወስ ውስተ ቤቱ ወገብረ ሎሙ ዳፍንተ ናእተ ወበልዑ።"),
    (11, 32, "'\" ወእንበለ ይስክቡ ሰብኣ ለይአቲ ሀገር ዐገትዎ ለቤቶሙ ዙሉ ሰብኦሙ ግቡሪ ንኤሰሙ ወፀቢዮሙ።"),
    (12, 1, "- ወጸውፅዎ ለሎጥ ወይቤልዎ አይቴ አሙንቱ አደው Ly 1) አለ ቦኡ ሣቤከ ሴሊተ ፣ አውጽፆሙ ኀቤነ ከመ ንሑርሙ።"),
    (12, 2, "ወወፅኣ ኀቤሆሙ ሎጥ ግበ ጭሣት RRR ወፀ ፀወ ጭሣተ ድግሬሆ = ወይቤሎሙ ሐሰ ለክሙ አግውያ፡ አታ ላዕለ አሉ።"),
    (
        12,
        3,
        "ወናሁ ብዩ ዩ አዋልድ ዘኢየአምራ ብአሴ፡ ወአወ ስኮን ለክሙ ወግበርዎን ዘከመ ይኤድመክሙ ፡ ወበሕቱ ላዕለ እሉ እደው አ ትግበሩ ምንተኒ ዐመፃ እለ ቦኡ ታሕ + ጽላሎተ ቤትየ።",
    ),
    (
        12,
        4,
        "ወይቤልዎ ሑር ከሓሐክ፡ ፀእክ ከመ ትጎድር ምስሌነ ወአክ ከመ ትኮንነነ፡ ወይእዜኒ ኪያከ ንሣቁ ፈድፋደ Ly አሪት. ዘልደት , ምፅራ የኢትዮጵያ አርቶዶክስ ተኖሕዶ ቤተ አምኔሆሙ ! ወተ'ሣየልዎም ሎቱ ፈድፋይ ወቀርቡ ከመ ይስብር ዎ ለኖሣግት።",
    ),
    (
        12,
        5,
        "ወአውዕኡ እደዊሆሙ ክአልክቱ ክደው ወሰሐብዎ ለሎ ጥ ወአብአዎ ግቤሆሙ ውስተ ቤት ወፀፀዉ ኖሣተ = 'ወለኣል ክቱ ክደው አለ ሀለዉ ቅድመ ኖጭሣቱ ለውእቱ ቤች ክሥርዎሙ አዕይንቲሆሙ ለንክሓለሙ ወለዐፀቢዮሙ፣ ወሠርሕ እንዘ የግሥሥዎ ለውእቱ ኖግት ወግጥእዎ።",
    ),
    (
        12,
        6,
        "ወይቤልዎ ለሎጥ እልክቱ መላእክት\" በኑ ዘብከ በዝየ ' ታክኃ ፡ አው ታሕማ፡ ወእመሂ ዶቁቅ ወአዋልድ ፡ ወለ . መስ ዘብ ፀርከ ፡ ዘተአምር TR ሀገር አውፅፀ - አሙ እምነ ዝንቱ መክን።",
    ),
    (
        12,
        7,
        ". እስመ ናማስና ንሕነ ለዛቲ መሕክን ኣስመ ዐብየ ከሮሙ በቅድመ ክግዚአብሔር ወፈነወነ ከመ ንደም ስሳ = ወወፅአ ሎጥ ግሸ ታሕማሆሁ 'ክለ ይነሥእአዎን ለክልኤሆን ኣአዋልዲሁ ወይቤሎሙ ተንሥጮ ወፃ አምዛቲ ሀገር ፡ እስመ ይደመስላጳ ኣግዚ አብሔር ለዛቲ ሀገር ፡ ወመሰሎሙ፡ ለታሕማሁ ከመ ዛበሥላሕሞ ይቤሎሙ።",
    ),
    (
        12,
        8,
        "ወፅበ ክኝ ክፈ ጽበሕ አሣዙ ያጐፇጕአዎ መላእክት ለሎጥ ወይቤልዎ ተንሥአ ወንሣክ ክልኤሆን አዋልዲክ ወብእ ሲተክ ፡ ወፃክ ከመ አንተሂ ኢትሙት በኃጢአቶሙ ለሰ ብዜ ዛቲ ሀንር።",
    ),
    (
        12,
        9,
        "ወስበ ጐንደየ አሣዝዎ እዴሁ እልክቱ እደው ወአድ ብእሲቱ ወክልኤሆን አዋልዳሁ ወአውፅእዎሙ እስመ ምህከሙ አግዚአብሔር = ወይቤልዎ ፀበ አውፅእዎ አፍኋ ኣድሣን ነፍሰካክ ወኢ ትነጽር ድሣሬክ ወኢትቁም ውስተ አድያሚሃ, ወውስተ ደብራ ለዛቲ ወገር ከመ ኢትርከብክ ለክ፤ አኪት።",
    ),
    (12, 10, "ወይቤሎሙ ሎጥ ብቍዑኔ አጋእዝትየ።"),
    (
        12,
        11,
        "አመ ረከብኩ ምሕረተ በቅድሜሟክሙ ወአዕበይክ ለም ሕረትከ ምስሌየ ከመ. ታሕይዋ ለነፍስየ • አንሰ ኢይክል አድዳኖ ርኣአስየ ውስተ ደብር ከመ ኢትርከበኒ አኪት ወእ.ይደይሙት = ወናሁ ዛቲ ህገር ቅርብት ዴእቲ ወንስቲት እሩ ዕየ. - ወጸድሣን ርእስየ፡ ወዚኢከነት ንስቲተ እምከመ ድሣነት i=) ነፍስዩ።",
    ),
    (12, 12, ") ወይቤሎ ናሁ አድሣንክዎ ለገጽክ ወበከመ ትቤ ጺይን ፈጥክ ለዛቲ ሀገር እንተ በአንቲ ሃበብክኒ።"),
    (12, 13, "አፍጥን ኣንክ ወጸድጎን ርእኣሰክ ህየ፡ እስመ ኢይክል ገቢረ ምንተኒ አስከ ትበጽሕ ፡ በአንተ ዝንቱ ተሰምየት ይእቲ ሀገር ሴጎር።"),
    (
        12,
        14,
        "ጠሠረቁ ፀሐዬ በዳበ ምድር ወሎጥኒ ቦአ ውስተ ሴጎር፥ ወአዝነመ እግዚአብሔር ላዕለ ባዶም ወገሞራ እሳተ መተየ እምኀበ እግዚአብሔር እም ሰማይ = ወገፍትአን ለእማንቱ አህጉር ወለአድያሚሆን ምስለ ሎሙ አለ ይነብሩ ውስቴቲቶን ወለኩሉ ዘርአ ምድሮሙ።",
    ),
    (12, 15, "ወነጻረራት ብክሲተ ሎዋ ድዳሬሃ ወኮነት ሐውልተ ዩው።"),
    (
        12,
        16,
        "ሠጌሠ አብርሃም ውስተ ዝኩ መክን ግበ ቁመ ቅድመ እግአብሔር = | መፍ ለዕቋ ግደ ሰድም ጠመግሞራ ወላዕስ አድሚ ፡ ወስበ ርአዩ ናሆ የፀወርግ ነድ አምድር ከመ ጢስ አቶን።",
    ),
    (12, 17, "ወክነ ዕበ ይምሰለን አግዚአብሔር ለአማንቱ አህጉር ወስዙሉሎ አድያሚሆን እለ ው'ስቴቁን የሣድር ሎጥ ተዘ ኻሮ ለአብርሃም '፡ ወክውፀአ ለሎጥ አማእከለ ሙክና።"),
    (12, 18, "ወፀርገ ሎጥ እምነ ሌጎር ወጓደረ ውስተ ደብር ወክል ኤቲ አዋልዲሁ ምክሌሁ ክስመ ፈርህ ነቢረ ውክተ ቤር ወነበረ ውከተ በዓት ውአቱ ወክልኤሆን አዋልዲጂሁ።"),
    (12, 19, "ወትቤላ እንቶ ትልሣቅ ለአንተ ትኝንአስ ናሁ አቡን አረ ጋዊ ውክቱ ፡ ወጸልቦ ሰብክ ዘይበውክ ጓሣቤነ ከመ ይዋ ለድ ሇከተ ኵሉ ምድር።"),
    (
        12,
        20,
        ", ንዒ ናስትም ወይነ ጸቡን ወንስክብ ምስሌሁ ወናቅም ዘር ጸም አቡ = ወጸስተያሁ ወይኝ ለአቡሆን ወበይአቲ ሌሊት ቦአት እንተ ትልግቅ ወሰከበት ምስለ አቡሃ ፡ ወኢያአመረ በበ ኪቦታ ወበተንሥጾታ።",
    ),
    (13, 1, ") ወእምዝ ትቤላ ክንተ.ትልሣቅ ለአንተ ትንአስ ናሁ ስክ ' ብኰ ትማልም ምስለ አቡነ ፡ ካዕበ ናስትዮ ወይነ ወስክቢ ምስሌሁ በዛቲ ሌሊት ወናቅም ዘርክ አም አቡነ።"),
    (13, 2, "ወጸስተያሁ ወይነ በይእቲ ሌሊት ወፀጾት ኣንተ ችን አክ ወሰከበት ምስለ አቡሃ ፡ Hii በዕኪቦታ ወበ ተንሥኔይታ።"),
    (13, 3, "ወፀንዳ ክልኤሆን አዋልዲጂሁ ዕሎኖ እምአቡሆን = | ወወለደት እንተ ትልሣቅ ወልደ ወሰመየቶ ስሞ ሞአብ ዘአምአቡየ ብሂል ወውእቱ. አቡሆሙ ለሞአበውያን።"),
    (
        13,
        4,
        ". መመስደት ወልይ እንተ ትንኣክስኒ ወሰመየቷ ከሞ አሞን -እንዛ ትብል ዘአምዛመድዩ፡ Shh አቡሆሙ ለኦአሞኝ IB) የኢትዮጵያ ኮርቶዶክክ ተኖሕሯ ቤተ a8 አሪት ዘልዴት ፡ ምዕራ i እስክ ድም።",
    ),
    (13, 5, "ወተንሥአ አብርሃም. እምህየ ወሖረ መንገለ ምድረ | አዜብ ፡ ወሣደረ ‘ማእከለ ቃዴስ ወማእከለ ቡሩ ወነበረ ውስተ ጌራራ።"),
    (13, 6, "ወይቤሎሙ ክብርሃም በአንተ ለራ ብአሲቁ እሣትዩ | ይአቲ ' ወለአክ አቤሜሌክ ንጉሠ ጌራራ ወነሥ’ኳ ለሰራ።"),
    (
        13,
        7,
        "ወስክ እግዚአብሔር ኀበ አቤሜሌክ በይኔቲ ሌሊት . . እንዘ ይነውም ወይቬሎ በሕልም ናሁ. ትመውት አንተ በእንተ ዛቲ ብኣሊት ኣንተ ነሣእክ እስመ ብአሷተ ብአሲ ይእቲ።",
    ),
    (13, 8, ". ) Pn የጺችዮጵያ ኮርቶዶኽክ ተዋሕዶ ቤች አሪት ዘልይት ፡ ምዕራ i ወአቤሜሌክሰ ኣ.ለከፋ፡ ወይቤ አቤሜሌክ ሕዝበኑ ዘኢያክአመረ በጽድቅ ትቀትል።"),
    (13, 9, ". ለሊሁ ይቤለኒ እሣትየ ይእቲ ፡ ወይአቲኒ ትቤለኒ ክሣቱ አነ ፡ ወበንጽሕ ልብ iy አደወ ገበርክዎ ለዝንቱ።"),
    (13, 10, "ወይቤሎ ኣግዚአብሔር በሕልም እነ አመር ከመ በንጹሕ ልቁ ገበርከ ለዝንቱ ወምሀኩክ ወዐቀብኩክ ከመ ኢተአብስ፡ ወበኣንተ ዝንቱ ኢሣደጉክ ትቅረባ።"),
    (13, 11, "ወይእዜኒ አግብአ ለብአሲ ብእሲቶ እስመ ነቢይ ውእቱ ወይጴሊ በእንቲአከ ወተሐዩ፣ ወእመሰ ኢያማሰአክ አሕ ምር ከመ ሞተ ትመውት አንተ ወዙሉ ዛዘዚጸስክ።"),
    (13, 12, ". ወተንመሥክ አቤሜሌክ በጽባሕ ወጻውዐ ሹሎ ድቁ ወን ሮሙ ዘንተ ነገረ ወፈርህዎ Rs ኵዙሱሉ ሰብጺ. ' ቤቱ ጥቁ።"),
    (
        13,
        13,
        "ወጸውያ አቤሜሌክ ለአብርሃም ወይቤሎ ምትኑ ኻዝ ዘገ በርኻ ላዕሌየ ወላዕለ OY የኅጢአት ዐቢይ. ዘጺገ ብሮ መሂ ይቤሎ PN ለጸብርሃም ምንተ. Caen ዝገበር ከሆ ለዝንቱ ነገር።",
    ),
    (13, 14, ". ወይቤሉ. ጾብርሃም ኣስመ አቤ ዮጊ አልቦ ፍርሃጥ እግዚ አብሔር ውስተዝ መክን፡ ወይቀትሉኒ በአንተ ብአሲትየ።"),
    (13, 15, "ወክዕበ አማን አግትየ ወይእቲ እመንገለ አቡዩ“ ወጸከ ክመንገለ አምየ ወከነተኒ ብእሲተ።"),
    (13, 16, "| ወክመ አውፅአኒ እግዚአብሔር እምቤተ አቡየ እቤላ ዘንተ ጽድቁ ግበሪ ሊተ ውስተ ዙሉ መክን ግበ ዘአነ በሊ አጎየ ውእቱ።"),
