    (14, 1, ", - ወጻጺለየ አብርሃም ሣበ እግዚአብሔር ወፈዛስ' አማዚአብ } ሑር ለአቤሜሌክ ወለብኣሷቱ ወለአዋልዲሁ ወለአእማ ቲሁ አለ ውስተ ቤቱ ወወለዳ።"),
