    (14, 19, '1 ፮ አሪት ዛልደት ፣ ምፅራ ወእምዝ ኃደረ ውስተ ሐቅለ ፋራን, ወነሥአት ሎቱ "እሙ ብእሲተ እምድረ ግብጽ።'),
