        18,
        2,
        "ኢፈቀዋዴት ይኣቲ ብአ | የኢትዮጵያ አርቶዶክስ ተዋሕዶ ቤተ ' አሪት ዘልደት ፡ ምፅ ለእግዚክየ ክብርሃም = ወክነ ዘእንበለ. አግልቅ ይልዮ በልብየ በጊዜ ወጽአት . - ርብቃ.ወት8ዩውር ቀሁታ ፡ ወወረደት ውክተ ዓዘቅት ወቀ ድሐት።",
