    (24, 36, "ወገብዙ ሣቤሁ ለያፅቋብ ክሙንቁ ሐዋርያት እለ ፈነ ወ ወይቤልዎ ሓርነ ሣበ ዔሳው እከ ወናሁ መጽአ ይት ; ቀበልክ ወጸርባዕቱ ም አት እደው ምስሌሁ።"),
