    (24, 43, "} እስመ ይቤ እአድዳን አምገጹ በዝንቱ አምኃ ዘይወስዱ =? ቅድሜሁ ወእምዝ አሬኡ ገጸ ቅድወ ከመ ይትቀበሎ | ) 1 [ [ ለገጽዩ በቋግን።"),
