    (25, 8, ".- .. | ' ወበጽሐ ያዕቆብ ጎበ ሎኝ እንተ ውስተ ምድረ ከነአን እንተ ይእቲ ቤቴል ፡ ውእቱ ወዙሉ ሕዝብ ዘም ስሌሁ።"),
    (25, 9, "ወነደቀ በሀየ ምሥዋሀ ወሰመየ ስሞ ለውእቱ መካን ቤቴል ፡ ኢስመ በህየ አስተርአዮ እግዚአብሔር ክመ ተሣ ጥጸ እምገጸ ኤሳው አሆ።"),
