    (25, 16, ". ወአምዝ አንዘ ህለወት ውክተ ሕማመ ወሊድ ትቤላ መወልዲት ኢትፍርሂ አስመ ዝኒ ይክውነከ፡ ወልደ።"),
    (25, 17, "| ወእምዝ ጸልጸቀት ከመ ትፃኣ ነፍጳ አስመ ቦቱ ከነ | ሙተታ፡ ወሰፅመየቶ ከሞ ወልደ ፃፅርየ ወኣቡሁሰ ሰመዮ . ብንያም።"),
    (25, 18, "ወሞተ ራል ወተቁብረት. ውስተ ፍኖት ዘኤፍ ' ራቻ አንተ ይአቲ ቤተ ልሔም።"),
    (25, 19, "| ወዞቂመ የዕቆብ ሐውልተ ላዕለ መቃብራ ወይእቲ ተፀምየት ሐውልተ መያብረ ራቱል አስከ ዮም።"),
    (25, 20, "ወእምዝ አንዘ ሀሎ አስራኤል ውስተ ይአቱ ምድር መረ ሮቤል ወሰከሸ ምስለ ዕቅብተ ያዕቆብ አቡሁ ምስለ በላ፡ ወሰምዐ አስራኤል ወኮነ አዅየ በቅድሜሁ።"),
