    (26, 24, "| ወሰበ ርአዩ ክግዊሁ ከመ ኪያሁ ያፈቅር አቡሆሙ i ' እምኩሎሙ ጸልክአዎ ወኢክህሉ ተናግሮ ሠናኛ።"),
