    (26, 28, ". ወይቤልዎ ነጊሠት ትነግሥ ላዕሌነ ወሚመ አግዚጸኑ ትቑው፣፣ ወጸፈድፈፉዱ ጓዲ id በአንተ ሕልሙ ወበ እንዯ ነግሩ።"),
