    (34, 10, "የአስር በዐፀደ ወይን ፅዋሎ. ወበዕፀ ዘይት አድን ወየ | ፲8 ፍውሐት አዕይንቲሁ እም ወይን ወፀኝጃዳ ከመ ሐሊብ | ፲፪ ስነኒኔሁ።"),
